import{_ as a,o as e,c as t,a5 as i}from"./chunks/framework.a5no_H3L.js";const g=JSON.parse('{"title":"DevTools 热部署","description":"改一行 Java 代码，传统做法是停掉应用重新 java -jar。DevTools 把这个「停掉重来」缩短成一次应用上下文的快速重建，代价是开发期多引入一个依赖。真正要理解的是它的触发边界，哪些文件变化会重启、哪些只会刷新浏览器。","frontmatter":{},"headers":[],"relativePath":"spring/02-spring-boot/chapter-07-devtools.md","filePath":"spring/02-spring-boot/chapter-07-devtools.md"}'),o={name:"spring/02-spring-boot/chapter-07-devtools.md"};function l(r,s,d,n,p,c){return e(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="devtools-热部署" tabindex="-1" data-src-line="1" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">DevTools 热部署 <a class="header-anchor" href="#devtools-热部署" aria-label="Permalink to &quot;DevTools 热部署&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="spring/02-spring-boot/chapter-07-devtools.md"><p data-src-line="3" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">改一行 Java 代码，传统做法是停掉应用重新 <code>java -jar</code>。DevTools 把这个「停掉重来」缩短成一次应用上下文的快速重建，代价是开发期多引入一个依赖。真正要理解的是它的触发边界，哪些文件变化会重启、哪些只会刷新浏览器。</p></blockquote><h2 id="_1-原理" tabindex="-1" data-src-line="5" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">1. 原理 <a class="header-anchor" href="#_1-原理" aria-label="Permalink to &quot;1. 原理&quot;">​</a></h2><p data-src-line="7" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">DevTools 用两个 ClassLoader 把类分成两类：</p><ul data-src-line="9" data-src-file="spring/02-spring-boot/chapter-07-devtools.md"><li data-src-line="9" data-src-file="spring/02-spring-boot/chapter-07-devtools.md"><strong>Base ClassLoader</strong> 加载第三方 jar，这些类在开发期几乎不变</li><li data-src-line="10" data-src-file="spring/02-spring-boot/chapter-07-devtools.md"><strong>Restart ClassLoader</strong> 加载 <code>target/classes</code> 下的项目代码，随时会变</li></ul><p data-src-line="12" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">检测到符合条件的 classpath 变化后，DevTools 丢弃旧的 Restart ClassLoader、新建实例，并重新启动应用上下文。Base ClassLoader 及其加载的类不动，需要重建的类少，因此通常比重新启动整个 JVM 更快。</p><p data-src-line="14" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">容易混淆的一点：<strong>DevTools 的「重启」不是重启 JVM，而是重建 Restart ClassLoader 并重启应用上下文</strong>。它省掉的是加载全部第三方依赖、重新初始化 JVM 这部分时间，而不是省掉整个启动流程。</p><h2 id="_2-引入依赖" tabindex="-1" data-src-line="16" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">2. 引入依赖 <a class="header-anchor" href="#_2-引入依赖" aria-label="Permalink to &quot;2. 引入依赖&quot;">​</a></h2><p data-src-line="18" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">DevTools 是开发期工具，Maven 项目把依赖声明为 <code>&lt;optional&gt;true&lt;/optional&gt;</code>，避免被下游模块传递引入：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;org.springframework.boot&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;spring-boot-devtools&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">optional</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;true&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">optional</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p data-src-line="28" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">Gradle 项目用 <code>developmentOnly</code> 达到同样效果：</p><div class="language-groovy vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">groovy</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dependencies {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    developmentOnly </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;org.springframework.boot:spring-boot-devtools&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="_3-livereload" tabindex="-1" data-src-line="36" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">3. LiveReload <a class="header-anchor" href="#_3-livereload" aria-label="Permalink to &quot;3. LiveReload&quot;">​</a></h2><p data-src-line="38" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">DevTools 内置 LiveReload 服务器。启用自动重启且浏览器插件已连接后，被监测到的资源变化可以触发浏览器刷新。</p><blockquote data-src-line="40" data-src-file="spring/02-spring-boot/chapter-07-devtools.md"><p data-src-line="40" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">本文以 Spring Boot 3.x 为基线。LiveReload 自 Spring Boot 4.1.0 起弃用，无替代方案。</p></blockquote><h2 id="_4-自动重启的触发机制" tabindex="-1" data-src-line="42" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">4. 自动重启的触发机制 <a class="header-anchor" href="#_4-自动重启的触发机制" aria-label="Permalink to &quot;4. 自动重启的触发机制&quot;">​</a></h2><p data-src-line="44" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">自动重启不是「改任何文件都重启」，它有明确的触发边界：</p><table tabindex="0"><thead data-src-line="46" data-src-file="spring/02-spring-boot/chapter-07-devtools.md"><tr data-src-line="46" data-src-file="spring/02-spring-boot/chapter-07-devtools.md"><th style="text-align:left;">变更类型</th><th style="text-align:left;">触发行为</th></tr></thead><tbody data-src-line="48" data-src-file="spring/02-spring-boot/chapter-07-devtools.md"><tr data-src-line="48" data-src-file="spring/02-spring-boot/chapter-07-devtools.md"><td style="text-align:left;">classpath 下被监视到且未被排除的 <code>.class</code> 与配置文件变化</td><td style="text-align:left;">触发 restart（重建 Restart ClassLoader）</td></tr><tr data-src-line="49" data-src-file="spring/02-spring-boot/chapter-07-devtools.md"><td style="text-align:left;"><code>/META-INF/maven</code>、<code>/META-INF/resources</code>、<code>/resources</code>、<code>/static</code>、<code>/public</code>、<code>/templates</code>、<code>**/*Test.class</code>、<code>git.properties</code> 等默认排除路径</td><td style="text-align:left;">不触发 restart；若 LiveReload 已启用且客户端已连接，可能触发浏览器刷新</td></tr></tbody></table><p data-src-line="51" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">默认排除列表里有两个容易忽略的项，测试类（<code>**/*Test.class</code>、<code>**/*Tests.class</code>）和构建元数据 <code>git.properties</code>。改了测试类不会触发重启，这是设计行为而非 bug。</p><h3 id="_4-1-文件监视器如何工作" tabindex="-1" data-src-line="53" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">4.1 文件监视器如何工作 <a class="header-anchor" href="#_4-1-文件监视器如何工作" aria-label="Permalink to &quot;4.1 文件监视器如何工作&quot;">​</a></h3><p data-src-line="55" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">DevTools 靠轮询检测变化，而不是监听文件系统事件。它每隔 <code>poll-interval</code> 扫一次 classpath 目录，发现变化后再等一个 <code>quiet-period</code> 静默期，确认没有更多文件落盘才触发重启：</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spring.devtools.restart.poll-interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1s    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 轮询间隔，默认 1s</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spring.devtools.restart.quiet-period</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=400ms  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 静默期，默认 400ms</span></span></code></pre></div><p data-src-line="62" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">静默期存在的原因，是 IDE 编译往往一批 class 文件先后落盘，如果发现第一个变化就立刻重启，后面的文件还没写完，重启就会读到不完整的 classpath。<code>quiet-period</code> 把连续变化合并成一次重启。网络磁盘慢、IDE 编译慢导致频繁重启或重启过早时，调大这两个值。自动重启默认开启，用 <code>spring.devtools.restart.enabled=false</code> 可以整体关闭。</p><h3 id="_4-2-触发文件-trigger-file" tabindex="-1" data-src-line="64" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">4.2 触发文件 trigger-file <a class="header-anchor" href="#_4-2-触发文件-trigger-file" aria-label="Permalink to &quot;4.2 触发文件 trigger-file&quot;">​</a></h3><p data-src-line="66" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">IDE 开启自动编译后，一次保存可能触发多次编译事件，DevTools 随之连续重启。用 <code>trigger-file</code> 指定一个文件当开关，只有它变化才触发重启：</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spring.devtools.restart.trigger-file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=.restart</span></span></code></pre></div><p data-src-line="72" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">之后想重启就 <code>touch .restart</code>，平时编译输出再变也不会误触发。适合多人项目，或不想被频繁重启打断的场景。</p><h3 id="_4-3-排除与额外监视" tabindex="-1" data-src-line="74" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">4.3 排除与额外监视 <a class="header-anchor" href="#_4-3-排除与额外监视" aria-label="Permalink to &quot;4.3 排除与额外监视&quot;">​</a></h3><p data-src-line="76" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">DevTools 默认监视 classpath 中的目录条目，被监视到且未被排除的变化触发 restart，默认排除路径的变化不触发 restart，静态资源与模板的修改不需要重启应用上下文。通过 <code>additional-paths</code> 可以监视 classpath 之外的目录，通过 <code>additional-exclude</code> 在默认排除列表基础上追加：</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># application.properties</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spring.devtools.restart.additional-exclude</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=custom-dir/**  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 在默认排除列表基础上追加排除路径</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spring.devtools.restart.additional-paths</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=src/main/conf    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 额外监视的非 classpath 路径</span></span></code></pre></div><p data-src-line="84" data-src-file="spring/02-spring-boot/chapter-07-devtools.md"><code>exclude</code> 和 <code>additional-exclude</code> 的区别要分清，<code>exclude</code> 替换整个默认列表，<code>additional-exclude</code> 在默认列表上追加。只想多排除一个目录时用后者，否则默认排除的静态资源和测试类会重新开始触发重启。</p><h2 id="_5-使用注意事项" tabindex="-1" data-src-line="86" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">5. 使用注意事项 <a class="header-anchor" href="#_5-使用注意事项" aria-label="Permalink to &quot;5. 使用注意事项&quot;">​</a></h2><ol data-src-line="88" data-src-file="spring/02-spring-boot/chapter-07-devtools.md"><li data-src-line="88" data-src-file="spring/02-spring-boot/chapter-07-devtools.md"><strong>生产环境禁用 DevTools</strong>。依赖声明为 <code>&lt;optional&gt;true&lt;/optional&gt;</code> 可避免下游模块传递引入；Spring Boot 打包插件默认会从重新打包的归档中排除 DevTools，不要在生产环境强制启用</li><li data-src-line="89" data-src-file="spring/02-spring-boot/chapter-07-devtools.md"><strong>修改后没有生效，先检查文件是否被监视</strong>。Java 代码要先编译成 classpath 上的 <code>.class</code>，DevTools 才检测得到。IDEA 默认不自动编译，需要手动构建（<code>Cmd+F9</code> 或 <code>Ctrl+F9</code>）或开启 <code>Build project automatically</code>；Eclipse 保存即编译。静态资源与模板则检查排除规则、LiveReload 配置及浏览器连接状态</li></ol><div class="warning custom-block"><p class="custom-block-title">反序列化与重启的冲突</p><p data-src-line="92" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">DevTools 重启会更换 Restart ClassLoader，使用标准 <code>ObjectInputStream</code> 反序列化的对象会因此失败，因为反序列化拿到的还是旧 ClassLoader 的类定义。需要反序列化的场景应改用 Spring 的 <code>ConfigurableObjectInputStream</code>，配合 <code>Thread.currentThread().getContextClassLoader()</code>。这是官方文档明确记录的已知限制。</p></div><h2 id="_6-全局配置" tabindex="-1" data-src-line="95" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">6. 全局配置 <a class="header-anchor" href="#_6-全局配置" aria-label="Permalink to &quot;6. 全局配置&quot;">​</a></h2><p data-src-line="97" data-src-file="spring/02-spring-boot/chapter-07-devtools.md">多个项目想统一 trigger-file 或轮询参数时，把配置放到 <code>$HOME/.config/spring-boot/spring-boot-devtools.properties</code>，对本机所有使用 DevTools 的应用生效。该文件不支持 profile，也不要放 profile 相关的分段。</p>`,36)])])}const k=a(o,[["render",l]]);export{g as __pageData,k as default};
